// Writes the source of src/generated/aggregation.ts from contracts/aggregation/v1/
// (reasons.json and histogram_buckets.json). The backend uses the generated file
// at runtime, so the reason ids and bucket edges exist in one place only
// (CLAUDE.md invariant 2; M3-T3 decision: generate, do not read the JSON at run time).
import { readFileSync } from 'node:fs';
import { join } from 'node:path';

export class AggregationGenerationError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'AggregationGenerationError';
  }
}

type JsonObject = Record<string, unknown>;

function isObject(value: unknown): value is JsonObject {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function fail(message: string): never {
  throw new AggregationGenerationError(message);
}

const ID = /^[a-z][a-z0-9_]*$/;

function id(value: unknown, where: string): string {
  if (typeof value !== 'string' || !ID.test(value)) fail(`${where}: not a snake_case id`);
  return value;
}

function int(value: unknown, where: string): number {
  if (typeof value !== 'number' || !Number.isSafeInteger(value) || value < 0) fail(`${where}: not a non-negative integer`);
  return value;
}

function list(value: unknown, where: string): unknown[] {
  if (!Array.isArray(value) || value.length === 0) fail(`${where}: not a non-empty array`);
  return value;
}

function object(value: unknown, where: string): JsonObject {
  if (!isObject(value)) fail(`${where}: not an object`);
  return value;
}

function quoted(values: unknown[], where: string): string {
  return values.map((v) => `'${id(v, where)}'`).join(', ');
}

/** The generated source for the parsed content of the two files. */
export function generateAggregationSource(reasonsFile: unknown, bucketsFile: unknown): string {
  const reasons = object(reasonsFile, 'reasons.json');
  const buckets = object(bucketsFile, 'histogram_buckets.json');
  const version = int(reasons.version, 'reasons.json version');
  if (int(buckets.version, 'histogram_buckets.json version') !== version) fail('reasons.json and histogram_buckets.json name different versions');
  const vocabularyVersion = int(buckets.vocabulary_version, 'vocabulary_version');

  const reasonIds = list(reasons.reasons, 'reasons').map((r) => id(object(r, 'reasons entry').id, 'reasons entry id'));
  if (new Set(reasonIds).size !== reasonIds.length) fail('reasons: repeated id');

  const seen = new Set<string>();
  const parameters = object(buckets.parameters, 'parameters');
  const parameterNames = Object.keys(parameters);
  if (parameterNames.length === 0) fail('parameters: empty');

  const out: string[] = [];
  out.push(`// Generated by backend/scripts/generate-contract.ts from contracts/aggregation/v${String(version)}/.`);
  out.push('// Do not edit. Change the contract, then run `npm run generate` in backend/.');
  out.push('');
  out.push("import type { Method } from './contract.ts';");
  out.push('');
  out.push('/** Version of contracts/aggregation/ these constants come from. */');
  out.push(`export const AGGREGATION_CONTRACT_VERSION = ${String(version)};`);
  out.push('/** Vocabulary version the bucket edges were checked against. */');
  out.push(`export const AGGREGATION_VOCABULARY_VERSION = ${String(vocabularyVersion)};`);
  out.push('');
  out.push('/** Plausibility reason ids, in the order the rules run (ADR 0035 point 4). */');
  out.push('export const REASON_IDS = [');
  for (const r of reasonIds) out.push(`  '${r}',`);
  out.push('] as const;');
  out.push('export type ReasonId = (typeof REASON_IDS)[number];');
  out.push('');
  out.push('export interface HistogramBucket {');
  out.push('  readonly id: string;');
  out.push("  /** Inclusive lower edge, in the parameter's scaled integer unit. */");
  out.push('  readonly from: number;');
  out.push('  /** Exclusive upper edge. */');
  out.push('  readonly to: number;');
  out.push('}');
  out.push('export interface HistogramSet {');
  out.push('  readonly id: string;');
  out.push('  readonly methods: readonly Method[];');
  out.push('  readonly buckets: readonly HistogramBucket[];');
  out.push('}');
  out.push('export interface HistogramParameter {');
  out.push('  readonly sourceFields: readonly string[];');
  out.push('  readonly scale: number;');
  out.push('  readonly sets: readonly HistogramSet[];');
  out.push('}');
  out.push('');
  out.push('export const HISTOGRAM_PARAMETER_IDS = [');
  for (const p of parameterNames) out.push(`  '${id(p, 'parameter')}',`);
  out.push('] as const;');
  out.push('export type HistogramParameterId = (typeof HISTOGRAM_PARAMETER_IDS)[number];');
  out.push('');
  out.push('/** Recipe parameter histograms, as in histogram_buckets.json. */');
  out.push('export const HISTOGRAM_PARAMETERS: Readonly<Record<HistogramParameterId, HistogramParameter>> = {');
  for (const name of parameterNames) {
    const p = object(parameters[name], name);
    out.push(`  ${name}: {`);
    out.push(`    sourceFields: [${quoted(list(p.source_fields, `${name}.source_fields`), `${name}.source_fields`)}],`);
    out.push(`    scale: ${String(int(p.scale, `${name}.scale`))},`);
    out.push('    sets: [');
    for (const s of list(p.sets, `${name}.sets`)) {
      const set = object(s, `${name} set`);
      const setId = id(set.id, `${name} set id`);
      out.push('      {');
      out.push(`        id: '${setId}',`);
      out.push(`        methods: [${quoted(list(set.methods, `${name}.${setId}.methods`), `${name}.${setId}.methods`)}],`);
      out.push('        buckets: [');
      for (const b of list(set.buckets, `${name}.${setId}.buckets`)) {
        const bucket = object(b, `${name}.${setId} bucket`);
        const bucketId = id(bucket.id, `${name}.${setId} bucket id`);
        if (seen.has(bucketId)) fail(`repeated bucket id ${bucketId}`);
        seen.add(bucketId);
        out.push(`          { id: '${bucketId}', from: ${String(int(bucket.from, bucketId))}, to: ${String(int(bucket.to, bucketId))} },`);
      }
      out.push('        ],');
      out.push('      },');
    }
    out.push('    ],');
    out.push('  },');
  }
  out.push('};');
  out.push('');
  return out.join('\n');
}

/** Reads both files of one version directory and generates the source. */
export function generateAggregationFromDir(dir: string): string {
  const read = (name: string): unknown => JSON.parse(readFileSync(join(dir, name), 'utf8')) as unknown;
  return generateAggregationSource(read('reasons.json'), read('histogram_buckets.json'));
}
